//
//  Screen-Space Reflections (SSR)
//  Native Metal Shader - Advanced Reflections
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float reflection_strength;
    float ray_steps;
    float step_size;
    float fade_distance;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Pseudo-depth from luminance
float getDepth(float3 color) {
    return 1.0 - dot(color, float3(0.299, 0.587, 0.114));
}

// Calculate reflection vector
float2 getReflectionUV(float2 uv, float3 normal, float depth) {
    // Simplified reflection calculation
    float2 reflection = reflect(float2(0.0, -1.0), normal.xy);
    return uv + reflection * depth * 0.1;
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    // Calculate pseudo-depth
    float depth = getDepth(color.rgb);

    // Calculate normal from luminance gradient
    float2 texelSize = 1.0 / uniforms.SourceSize.xy;
    float depthRight = getDepth(sourceTexture.sample(textureSampler, in.texCoord + float2(texelSize.x, 0.0)).rgb);
    float depthUp = getDepth(sourceTexture.sample(textureSampler, in.texCoord + float2(0.0, texelSize.y)).rgb);

    float3 normal = normalize(float3(
        depth - depthRight,
        depth - depthUp,
        1.0
    ));

    // Ray marching for reflections
    float3 reflection = float3(0.0);
    float2 rayUV = in.texCoord;
    float2 rayDir = reflect(float2(0.0, -1.0), normal.xy) * uniforms.step_size;

    int steps = int(uniforms.ray_steps);
    float totalWeight = 0.0;

    for (int i = 0; i < steps; i++) {
        rayUV += rayDir * texelSize;

        // Check bounds
        if (rayUV.x < 0.0 || rayUV.x > 1.0 || rayUV.y < 0.0 || rayUV.y > 1.0) {
            break;
        }

        float3 sampleColor = sourceTexture.sample(textureSampler, rayUV).rgb;
        float sampleDepth = getDepth(sampleColor);

        // Weight based on depth similarity
        float depthDiff = abs(depth - sampleDepth);
        float weight = exp(-depthDiff * 10.0);

        // Fade with distance
        float dist = float(i) / float(steps);
        weight *= 1.0 - smoothstep(0.0, uniforms.fade_distance, dist);

        reflection += sampleColor * weight;
        totalWeight += weight;
    }

    if (totalWeight > 0.0) {
        reflection /= totalWeight;
    }

    // Mix reflection with original
    float reflectionMask = smoothstep(0.3, 0.7, depth);
    color.rgb = mix(color.rgb, reflection, reflectionMask * uniforms.reflection_strength);

    return color;
}

